// Count partitions of 20 into distinct parts
// dp[i+1][j+1] = number of ways to partition j using distinct parts from {1,...,i}
// (offset by 1 since Magma sequences are 1-indexed)

n := 20;
dp := [[0 : j in [1..n+1]] : i in [1..n+1]];
dp[1][1] := 1;  // dp[part=0][sum=0] = 1

for i in [1..n] do
    for j in [1..n+1] do
        // don't use part i
        dp[i+1][j] := dp[i][j];
        // use part i: requires sum >= i
        if j - i ge 1 then
            dp[i+1][j] +:= dp[i][j-i];
        end if;
    end for;
end for;

print dp[n+1][n+1];

