// Count partitions of 20 into distinct parts using dynamic programming
// dp[s] = number of ways to partition s using distinct parts from {1..20}
n := 20;
dp := [0 : i in [0..n]];
dp[1] := 1; // index 1 = sum 0, initialize to 1
// Reindex: use 1-indexed array where dp[i+1] = ways to make sum i
dp2 := [0 : i in [1..n+1]];
dp2[1] := 1; // dp2[i] represents sum i-1
for part := 1 to n do
    // iterate backwards to ensure each part used at most once
    for s := n to part by -1 do
        dp2[s+1] +:= dp2[s+1-part];
    end for;
end for;
print dp2[n+1];

