// Count partitions of 20 into distinct parts
// dp2[i+1] = number of ways to make sum i using distinct parts
n := 20;
dp2 := [0 : i in [1..n+1]];
dp2[1] := 1; // sum 0 has 1 way (empty partition)

// For each part k from 1 to n, update in reverse (to ensure each part used at most once)
for k := 1 to n do
    for s := n to k by -1 do
        dp2[s+1] := dp2[s+1] + dp2[s-k+1];
    end for;
end for;

print dp2[n+1];

